'use strict';
const $=id=>document.getElementById(id);let state={runs:[],comparisons:[],token:''};
function option(select,value,label){const item=document.createElement('option');item.value=value;item.textContent=label;select.append(item);}
function selection(){return {bundle_id:$('bundle-id').value,selections:[...$('snapshots').selectedOptions].map(o=>JSON.parse(o.value)),comparison_ids:[...$('comparisons').selectedOptions].map(o=>o.value),actor:$('actor').value,note:$('note').value};}
function summary(){const data=selection();$('selection').textContent=JSON.stringify({explicit_snapshots:data.selections,comparisons:data.comparison_ids,referenced_snapshots:'Automatically resolved by the server',execution_authorized:false,layer_a_status:'LEGAL_REVIEW_REQUIRED'},null,2);}
function snapshots(){const old=new Set([...$('snapshots').selectedOptions].map(o=>o.value));$('snapshots').replaceChildren();for(const run of state.runs){const history=$('historical').checked?run.history:run.history.slice(-1);for(const event of history){const value=JSON.stringify({run_id:run.run_id,sequence:event.sequence});option($('snapshots'),value,run.run_id+' · '+event.sequence+' · '+event.state.stage);if(old.has(value))$('snapshots').lastElementChild.selected=true;}}summary();}
$('historical').onchange=snapshots;$('snapshots').onchange=summary;$('comparisons').onchange=summary;
$('bundle-form').onsubmit=async e=>{e.preventDefault();const button=document.querySelector('#bundle-form button');button.disabled=true;try{const data=selection();const response=await fetch('/api/review-bundles',{method:'POST',headers:{'Content-Type':'application/json','X-Portfolio-Token':state.token},body:JSON.stringify(data)});if(!response.ok)throw Error((await response.json()).error);const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;const header=response.headers.get('Content-Disposition')||'';const match=header.match(/filename="([^"]+)"/);link.download=match?match[1]:'synthetic-review.zip';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('message').textContent='Selected review ZIP built. Check the manifest and selected notes before sharing; no authority is granted.';}catch(error){$('message').textContent=error.message;}finally{button.disabled=false;}};
(async()=>{try{const response=await fetch('/api/scenario-comparisons');if(!response.ok)throw Error('Could not load review sources');state=await response.json();snapshots();for(const comparison of state.comparisons)option($('comparisons'),comparison.comparison_id,comparison.comparison_id+' · '+comparison.workflow);summary();}catch(error){$('message').textContent=error.message;}})();
